const apiKey = $input.first().json.api_key;
if (!apiKey || apiKey !== $env.N8N_API_KEY) {
  throw new Error('Unauthorized');
}
const body = $input.first().json;
const { brand_id, frequency, post_times, topic_discovery_day, analytics_day } = body;
if (!brand_id) throw new Error('Missing brand_id');

return [{
  json: {
    brand_id,
    frequency: frequency || '3',
    post_times: post_times || '["09:00","12:00","18:00"]',
    topic_discovery_day: topic_discovery_day || 'monday',
    analytics_day: analytics_day || 'sunday',
    log_id: 'us-' + $now.toISO().replace(/[^0-9]/g, '').slice(0, 17),
    started_at: $now.toISO()
  }
}];

const data = $('驗證請求').first().json;

// 將星期轉換為 cron 格式
const dayMap = {
  monday: 1, tuesday: 2, wednesday: 3,
  thursday: 4, friday: 5, saturday: 6, sunday: 0
};

const topicDay = dayMap[data.topic_discovery_day] ?? 1;
const analyticsDay = dayMap[data.analytics_day] ?? 0;

// 解析發文時間
let postTimes;
try {
  postTimes = JSON.parse(data.post_times);
} catch {
  postTimes = ['09:00', '12:00', '18:00'];
}

// 產生排程摘要
const summary = {
  brand_id: data.brand_id,
  schedules: {
    topic_discovery: {
      description: `每週${['日','一','二','三','四','五','六'][topicDay]}自動搜尋主題`,
      cron: `0 9 * * ${topicDay}`,
      workflow: 'topic-discovery'
    },
    content_generation: {
      description: `主題搜尋後隔天自動生成貼文`,
      cron: `0 10 * * ${(topicDay + 1) % 7}`,
      workflow: 'content-generation'
    },
    post_publishing: {
      description: `每週 ${data.frequency} 次，時段：${postTimes.join(', ')}`,
      times: postTimes,
      frequency: data.frequency,
      workflow: 'post-scheduler'
    },
    analytics_collection: {
      description: `每週${['日','一','二','三','四','五','六'][analyticsDay]}收集數據`,
      cron: `0 8 * * ${analyticsDay}`,
      workflow: 'analytics-collection'
    },
    weekly_optimization: {
      description: `數據收集後自動執行 AI 優化`,
      cron: `0 10 * * ${analyticsDay}`,
      workflow: 'weekly-optimization'
    },
    customer_identification: {
      description: '每日掃描新留言識別潛在客戶',
      cron: '0 20 * * *',
      workflow: 'customer-identification'
    }
  },
  message: '排程已更新。請在 n8n 中確認 cron 觸發器已同步更新。'
};

// 注意：在實際部署時，這裡應該透過 n8n API 動態更新 cron 觸發器
// 目前先記錄設定，由管理員手動在 n8n 中調整

return [{ json: summary }];
